from collections import Counter
class Solution:
    def getLargestOutlier(self, nums: List[int]) -> int:
        cnt = Counter(nums)
        T = sum(nums)
        ans = float('-inf')
        for x in nums:
            rem = T - x
            if rem % 2:
                continue
            cnt[x] -= 1
            if cnt[rem // 2] > 0:
                ans = max(ans, x)
            cnt[x] += 1
        return ans

