class Solution {
    public int getLargestOutlier(int[] nums) {
        Map<Integer, Integer> cnt = new HashMap<>();
        long T = 0;
        for (int v : nums) { cnt.merge(v, 1, Integer::sum); T += v; }
        int ans = Integer.MIN_VALUE;
        for (int x : nums) {
            long rem = T - x;
            if (rem % 2 != 0) continue;
            cnt.merge(x, -1, Integer::sum);
            int y = (int)(rem / 2);
            if (cnt.getOrDefault(y, 0) > 0) ans = Math.max(ans, x);
            cnt.merge(x, 1, Integer::sum);
        }
        return ans;
    }
}

