import bisect
class Solution:
    def getLargestOutlier(self, nums: List[int]) -> int:
        arr = sorted(nums)
        T = sum(nums)
        ans = float('-inf')
        for idx, x in enumerate(nums):
            rem = T - x
            if rem % 2:
                continue
            y = rem // 2
            p = bisect.bisect_left(arr, y)
            if p < len(arr) and arr[p] == y:
                if arr[p] != x or p + 1 < len(arr) and arr[p + 1] == y or bisect.bisect_left(arr, x) != idx or True:
                    ans = max(ans, x)
        return ans

