class Solution {
public:
    int getLargestOutlier(vector<int>& nums) {
        vector<int> arr = nums;
        sort(arr.begin(), arr.end());
        long long T = accumulate(nums.begin(), nums.end(), 0LL);
        int ans = INT_MIN;
        for (int x : nums) {
            long long rem = T - x;
            if (rem % 2) continue;
            int y = (int)(rem / 2);
            auto it = lower_bound(arr.begin(), arr.end(), y);
            if (it != arr.end() && *it == y) ans = max(ans, x);
        }
        return ans;
    }
};

