class Solution {
    public int getLargestOutlier(int[] nums) {
        int[] arr = nums.clone();
        Arrays.sort(arr);
        long T = 0;
        for (int v : nums) T += v;
        int ans = Integer.MIN_VALUE;
        for (int x : nums) {
            long rem = T - x;
            if (rem % 2 != 0) continue;
            int y = (int)(rem / 2);
            int p = Arrays.binarySearch(arr, y);
            if (p >= 0) ans = Math.max(ans, x);
        }
        return ans;
    }
}

