var getLargestOutlier = function(nums) {
    const arr = [...nums].sort((a, b) => a - b);
    let T = 0;
    for (const v of nums) T += v;
    let ans = -Infinity;
    for (const x of nums) {
        const rem = T - x;
        if (rem % 2 !== 0) continue;
        const y = rem / 2;
        let lo = 0, hi = arr.length - 1, found = false;
        while (lo <= hi) {
            const mid = (lo + hi) >> 1;
            if (arr[mid] === y) { found = true; break; }
            if (arr[mid] < y) lo = mid + 1; else hi = mid - 1;
        }
        if (found) ans = Math.max(ans, x);
    }
    return ans;
};
